function petshop_pragma_prepare( $year, $month ) {
    global $wpdb;
    $per  = sprintf( '%04d-%02d', $year, $month );
    $last = ( new DateTime( $per . '-01', wp_timezone() ) )->format( 'Y-m-t' );
    $res  = array( 'period' => $per, 'orders' => array(), 'veluojancios' => array(), 'anuliuotos' => array(), 'errors' => array(), 'warnings' => array(), 'files' => array(), 'sum' => array() );

    $ids = $wpdb->get_col( "SELECT DISTINCT order_id FROM {$wpdb->prefix}wc_orders_meta WHERE meta_key='_petshop_avpn_number' AND meta_value<>''" );
    foreach ( $ids as $id ) {
        $o = wc_get_order( (int) $id );
        if ( ! $o || 'shop_order' !== $o->get_type() ) continue;
        if ( $o->get_meta( '_ps_pragma_eksportuota' ) ) continue;
        $d = petshop_pragma_doc_date( $o );
        if ( ! $d || $d < PS_PRAGMA_NUO || $d > $last ) continue;
        $st = $o->get_status();
        if ( in_array( $st, array( 'cancelled', 'failed', 'trash' ), true ) ) {
            if ( ! $o->get_meta( '_ps_pragma_anuliuota_pranesta' ) ) $res['anuliuotos'][] = $o;
            continue;
        }
        if ( 'invoice' !== $o->get_meta( '_petshop_invoice_document_type' ) ) {
            $res['errors'][] = '#' . $o->get_order_number() . ' ' . $o->get_meta( '_petshop_avpn_number' ) . ': turi AVPN, bet dokumento tipas „' . $o->get_meta( '_petshop_invoice_document_type' ) . '“';
            continue;
        }
        if ( ! in_array( $st, array( 'processing', 'completed', 'refunded', 'on-hold' ), true ) ) {
            $res['errors'][] = '#' . $o->get_order_number() . ': netikėta būsena ' . $st;
            continue;
        }
        if ( 'on-hold' === $st && '1' !== (string) $o->get_meta( '_ps_pvm_sf_neapmoketa' ) ) {
            $res['errors'][] = '#' . $o->get_order_number() . ': on-hold su AVPN be įstaigos žymos';
            continue;
        }
        if ( substr( $d, 0, 7 ) < $per ) $res['veluojancios'][] = $o;
        $res['orders'][] = $o;
    }
    usort( $res['orders'], function( $a, $b ) { return strcmp( $a->get_meta( '_petshop_avpn_number' ), $b->get_meta( '_petshop_avpn_number' ) ); } );

    if ( empty( $res['orders'] ) ) { $res['errors'][] = 'Nėra nė vienos s/f – nesiunčiama (patikrinti rankiniu būdu).'; return $res; }

    // --- 1 patikra: duomenys iš DB ---
    $seen = array(); $tot = 0; $vat = 0; $ex = 0;
    $test_emails = array( 'terra@gyvunai.lt', 'raimundas@gyvunai.lt', 'terra@petshop.lt' );
    foreach ( $res['orders'] as $o ) {
        $nr = '#' . $o->get_order_number(); $av = (string) $o->get_meta( '_petshop_avpn_number' );
        if ( ! preg_match( '/^AVPN\d{6}$/', $av ) ) $res['errors'][] = "$nr: blogas AVPN numeris „{$av}“";
        if ( isset( $seen[ $av ] ) ) $res['errors'][] = "$nr: AVPN {$av} DUBLIKATAS (taip pat #{$seen[$av]})";
        $seen[ $av ] = $o->get_order_number();
        $t = round( (float) $o->get_total(), 2 ); $v = round( (float) $o->get_total_tax(), 2 ); $b = round( $t - $v, 2 );
        if ( $t <= 0 ) $res['errors'][] = "$nr $av: suma $t";
        if ( $b > 0 && abs( $v - $b * 0.21 ) > max( 0.05, $b * 0.003 ) ) $res['errors'][] = "$nr $av: PVM $v neatitinka 21 % nuo $b";
        $em = strtolower( trim( $o->get_billing_email() ) );
        if ( in_array( $em, $test_emails, true ) || preg_match( '/\btest/i', $o->get_billing_first_name() . ' ' . $o->get_billing_last_name() ) ) $res['errors'][] = "$nr $av: panašu į TESTINĮ užsakymą ($em)";
        if ( '' === petshop_pragma_get_client_name( $o ) ) $res['errors'][] = "$nr $av: tuščias kliento vardas";
        if ( ! preg_match( '/^\d{7,10}$/', petshop_pragma_get_client_id( $o ) ) ) $res['errors'][] = "$nr $av: blogas kliento ID";

