function petshop_pragma_run_export( $year, $month, $opt = array() ) {
    $per  = sprintf( '%04d-%02d', $year, $month );
    $test = ! empty( $opt['testas'] );
    $try  = isset( $opt['bandymas'] ) ? (int) $opt['bandymas'] : 1;
    $sent = (array) get_option( 'petshop_pragma_issiusta', array() );
    if ( ! $test && isset( $sent[ $per ] ) && empty( $opt['pakartoti'] ) ) {
        petshop_pragma_log( $per . ': NESIUNČIAMA – jau išsiųsta ' . $sent[ $per ] . ' (apsauga nuo dvigubo siuntimo)' );
        return array( 'ok' => false, 'msg' => 'jau išsiųsta ' . $sent[ $per ] );
    }
    $lock = 'ps_pragma_lock_' . $per;
    if ( get_transient( $lock ) ) { petshop_pragma_log( $per . ': NESIUNČIAMA – kitas siuntimas vyksta' ); return array( 'ok' => false, 'msg' => 'vyksta kitas' ); }
    set_transient( $lock, 1, 15 * MINUTE_IN_SECONDS );
    $dir = ''; $paths = array();
    try {
        // 1–2 patikros (prepare), 3 patikra – antras paruošimas turi duoti tuos pačius failus
        $p  = petshop_pragma_prepare( $year, $month );
        $p2 = petshop_pragma_prepare( $year, $month );
        if ( md5( serialize( $p['files'] ) ) !== md5( serialize( $p2['files'] ) ) ) $p['errors'][] = 'Du paruošimai davė skirtingus failus – duomenys keičiasi, bandyti vėliau';
        if ( ! empty( $p['errors'] ) ) {
            petshop_pragma_log( $per . ': NESIŲSTA – patikroje klaidų ' . count( $p['errors'] ) . ': ' . mb_substr( implode( '; ', $p['errors'] ), 0, 300 ) );
            petshop_pragma_alert( '⚠ Pragma ' . $per . ' NESIŲSTA – rastos klaidos', petshop_pragma_report_text( $p ) );
            return array( 'ok' => false, 'msg' => 'klaidos' );
        }
        // 4 patikra: įrašyti failai perskaitomi ir lyginami
        $dir = trailingslashit( sys_get_temp_dir() ) . 'ps_pragma_' . $per . '_' . wp_generate_password( 6, false, false ) . '/';
        wp_mkdir_p( $dir );
        foreach ( $p['files'] as $fn => $c ) {
            file_put_contents( $dir . $fn, $c );
            if ( (string) @file_get_contents( $dir . $fn ) !== $c ) $p['errors'][] = "$fn: įrašytas failas nesutampa";
            $paths[] = $dir . $fn;
        }
        if ( ! empty( $p['errors'] ) ) {
            petshop_pragma_log( $per . ': NESIŲSTA – failų įrašymo klaida' );
            petshop_pragma_alert( '⚠ Pragma ' . $per . ' NESIŲSTA – failų klaida', petshop_pragma_report_text( $p ) );
            return array( 'ok' => false, 'msg' => 'failai' );
        }

        $to      = $test ? 'terra@petshop.lt' : apply_filters( 'petshop_pragma_recipient', 'info@audac.lt' );
        $subject = ( $test ? '[TEST] ' : '' ) . 'Petshop.lt pardavimai ' . $per;
        $body    = "Laba diena,\n\nPrisegti " . $per . ' menesio pardavimų failai Pragma importui (' . $p['sum']['n'] . ' PVM s/f, ' . $p['orders'][0]->get_meta( '_petshop_avpn_number' ) . '–' . end( $p['orders'] )->get_meta( '_petshop_avpn_number' ) . ").\n";
        if ( $p['veluojancios'] ) { $body .= "\nPavėluotai įtrauktos (ankstesnio mėnesio data):\n"; foreach ( $p['veluojancios'] as $o ) $body .= '  - ' . $o->get_meta( '_petshop_avpn_number' ) . ' (' . petshop_pragma_doc_date( $o ) . ")\n"; }
        if ( $p['anuliuotos'] ) { $body .= "\nIšrašytos, bet užsakymas atšauktas (į failus neįtrauktos):\n"; foreach ( $p['anuliuotos'] as $o ) $body .= '  - ' . $o->get_meta( '_petshop_avpn_number' ) . ' (' . petshop_pragma_doc_date( $o ) . ', ' . number_format( (float) $o->get_total(), 2, ',', '' ) . " EUR)\n"; }
        $body .= "\nPetshop.lt sistema";

        $err = '';
        $cb  = function( $e ) use ( &$err ) { $err = $e->get_error_message(); };
        add_action( 'wp_mail_failed', $cb );
        $ok = wp_mail( $to, $subject, $body, array( 'Content-Type: text/plain; charset=UTF-8' ), $paths );
        remove_action( 'wp_mail_failed', $cb );
        wp_mail( 'terra@petshop.lt', '[PRAGMA] ' . $subject . ' - ' . ( $ok ? 'OK' : 'NEPAVYKO' ), $body . "\n\n[Siuntimas i " . $to . ': ' . ( $ok ? 'priimta' : 'NEPAVYKO ' . $err ) . "]\n" . petshop_pragma_summary_line( $p ), array( 'Content-Type: text/plain; charset=UTF-8' ), $paths );

        if ( ! $ok ) {
            petshop_pragma_log( $per . ': NEPAVYKO išsiųsti (' . $try . ' bandymas): ' . ( $err ? $err : 'wp_mail=false' ) );
            if ( ! empty( $opt['auto'] ) && ! $test && $try < 3 ) {
                wp_schedule_single_event( time() + DAY_IN_SECONDS, 'petshop_pragma_retry', array( $year, $month, $try + 1 ) );
                $kitas = 'Kitas bandymas po 24 h (' . ( $try + 1 ) . ' iš 3).';
            } else {
                $kitas = 'Daugiau automatinių bandymų nebus – reikia rankinio.';
            }
            petshop_pragma_alert( '⚠ Pragma ' . $per . ' NEPAVYKO išsiųsti', 'Klaida: ' . ( $err ? $err : 'wp_mail=false' ) . "\n" . $kitas . "\n\n" . petshop_pragma_report_text( $p ) );
            return array( 'ok' => false, 'msg' => $err ? $err : 'wp_mail=false' );
        }
        if ( $test ) {
            petshop_pragma_log( $per . ': TESTAS išsiųstas tik terra@petshop.lt. ' . petshop_pragma_summary_line( $p ) );
            return array( 'ok' => true, 'msg' => 'testas' );
        }
        foreach ( $p['orders'] as $o )     { $o->update_meta_data( '_ps_pragma_eksportuota', $per ); $o->save_meta_data(); }
        foreach ( $p['anuliuotos'] as $o ) { $o->update_meta_data( '_ps_pragma_anuliuota_pranesta', $per ); $o->save_meta_data(); }
        $sent[ $per ] = current_time( 'Y-m-d H:i' );
        update_option( 'petshop_pragma_issiusta', $sent, false );
        petshop_pragma_log( $per . ': IŠSIŲSTA ' . $to . ' (SMTP priėmė). ' . petshop_pragma_summary_line( $p ) );
        return array( 'ok' => true, 'msg' => 'išsiųsta' );
    } finally {
        foreach ( $paths as $x ) @unlink( $x );
        if ( $dir ) @rmdir( $dir );
        delete_transient( $lock );
    }
}

