function petshop_pragma_generate_imones( $orders ) {
    $lines = array();

    foreach ( $orders as $order ) {
        $client_id = petshop_pragma_get_client_id( $order );
        $name      = petshop_pragma_get_client_name( $order );
        $address   = petshop_pragma_clean_value( $order->get_billing_address_1() );
        $country   = $order->get_billing_country() ?: 'LT';
        $phone     = petshop_pragma_clean_value( $order->get_billing_phone() );
        $email     = petshop_pragma_clean_value( $order->get_billing_email() );
        $company   = petshop_pragma_clean_value( $order->get_billing_company() );
        $vat_code  = $order->get_meta( '_billing_vat_code' ) ?: '';

        // PVM kodas stulpelis (6): tik jei imone
        $vat_field = $vat_code ? $vat_code : '';

        // Paskutinis stulpelis: 1=fizinis, 0=juridinis
        $type = ( $company || $vat_code ) ? '0' : '1';

        $line = implode( "\t", array(
            $client_id,     // 1: ID
            $name,          // 2: Vardas/pavadinimas
            $client_id,     // 3: ID (kartojas)
            $name,          // 4: Vardas (kartojas)
            $address,       // 5: Adresas
            $vat_field,     // 6: PVM kodas
            '',             // 7: tuscias
            '',             // 8: tuscias
            $country,       // 9: Salis
            $phone,         // 10: Telefonas
            $name,          // 11: Vardas (kartojas)
            $email,         // 12: El. pastas
            $type,          // 13: Tipas
        ) );

        $lines[] = $line;
    }

    return implode( "\n", $lines );
}

