function petshop_pragma_get_client_id( $order ) {
    $company  = $order->get_billing_company();
    $vat_code = $order->get_meta( '_billing_vat_code' );

    // Imone su imones kodu
    if ( $vat_code && preg_match( '/\d{7,9}/', $vat_code, $m ) ) {
        return '3' . $m[0];
    }

    // Fizinis asmuo - ID pagal uzsakymo numeri, visada 7 skaitmenys
    // Formulė: "2" + order_number padded to 5 digits + "5"
    $order_nr = (int) $order->get_order_number();
    return '2' . str_pad( $order_nr, 5, '0', STR_PAD_LEFT ) . '5';
}

function petshop_pragma_get_client_name( $order ) {
    $company = trim( $order->get_billing_company() );
